// Design sandbox: local state only. No real device, identity or media APIs.
(() => {
  const peers=[
    {name:'Family PC',id:'000000201',os:'Windows',index:0,online:true,favorite:true,family:true},
    {name:'Work Laptop',id:'000000202',os:'Windows',index:1,online:true,favorite:false,family:false},
    {name:'Test phone',id:'000000203',os:'iOS · концепт',index:2,online:true,favorite:false,family:false},
    {name:'Test Android',id:'000000204',os:'Android · демо',index:3,online:true,favorite:false,family:false},
    {name:'Family Laptop',id:'000000205',os:'Windows',index:1,online:false,favorite:true,family:false}
  ];
  let current='home',list='recent',chosen=peers[0],otp='DEMO01',shown=false,permanent=false,pendingAction=null,paneTimer=null,suggestIndex=-1;
  const d=$('#prototype-dialog');
  const descriptions={home:'Главное окно — композиция текущего Windows-клиента. Данные вымышлены.',connect:'Подключение и диагностика. Переключатели P2P / Relay относятся только к сетевой симуляции.',family:'Сопряжение, запрос помощи и доверенные устройства. Вы управляете обеими сторонами в демо.',call:'Исходящий и входящий звонок. Кадры и индикаторы голоса нарисованы; медиа не передаются.',files:'Передача файлов внутри симуляции. Для своего файла используются только имя и размер.',screen:'Удалённый Windows-экран: откройте Блокнот, переместите окно, попробуйте ввод.',mobile:'Концепты мобильных экранов. iOS — просмотр. Android — ввод с разрешением в демо.'};
  function dialog(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;if(d.showModal)d.showModal();else d.setAttribute('open','');}
  function closeDialog(){if(d.close)d.close();else d.removeAttribute('open');}
  $('#dialog-close').onclick=closeDialog;
  d.addEventListener('click',e=>{if(e.target===d){const rect=d.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});
  async function copyMock(value){try{if(!navigator.clipboard?.writeText)throw new Error('clipboard unavailable');await navigator.clipboard.writeText(value);toast('Скопированы вымышленные данные демо.');}catch{dialog('Данные демо','<p>Можно выделить и скопировать текст вручную.</p><pre class="dialog-share" id="manual-copy"></pre>');$('#manual-copy').textContent=value;}}
  function showScenario(value,scroll=false){
    current=value;$$('[data-scenario]').forEach(b=>{const active=b.dataset.scenario===value;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;b.setAttribute('aria-controls',value==='home'?'scenario-home':value==='family'||value==='call'?'scenario-family':'scenario-session');});
    $('#scenario-home').hidden=value!=='home';$('#scenario-family').hidden=!(value==='family'||value==='call');$('#scenario-session').hidden=['home','family','call'].includes(value);$('#scenario-caption').textContent=descriptions[value];
    if(value==='family'||value==='call')document.querySelector('[data-journey="'+(value==='call'?'call':'family')+'"]').click();
    if(!['home','family','call'].includes(value)){resizePackets();if(value==='files'&&connected&&selected<2)openFiles();if(value==='screen'&&connected){$('#remote-screen').hidden=false;syncRights();}if(value==='connect'){$('.session').classList.remove('inspector-collapsed');$('.inspector-toggle').textContent='▾ Диагностика соединения · симулятор сети';$('.inspector-toggle').setAttribute('aria-expanded','true');}else{$('.session').classList.add('inspector-collapsed');$('.inspector-toggle').textContent='▸ Диагностика соединения · симулятор сети';$('.inspector-toggle').setAttribute('aria-expanded','false');}}
    if(scroll)$('#demo').scrollIntoView({behavior:paused?'auto':'smooth',block:'start'});
  }
  function focusScenario(value){showScenario(value,true);document.querySelector('[data-scenario="'+value+'"]').focus({preventScroll:true});}
  $$('[data-scenario]').forEach(b=>b.onclick=()=>{if(b.dataset.scenario==='files'||b.dataset.scenario==='screen'){showScenario(b.dataset.scenario);if(!connected)startSession(chosen.online&&chosen.index<2?chosen:peers[0],b.dataset.scenario==='files'?'files':'screen');}else if(b.dataset.scenario==='mobile'){showScenario('mobile');if(selected<2||!connected)startSession(peers[2],'mobile');}else showScenario(b.dataset.scenario);});
  $('.scenario-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const buttons=$$('[data-scenario]');const i=buttons.indexOf(document.activeElement);if(i<0)return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[n].click();buttons[n].focus();});
  $$('[data-jump]').forEach(b=>b.onclick=()=>{focusScenario(b.dataset.jump);if(b.dataset.jump==='files')startSession(peers[0],'files');});
  $('#return-home').onclick=()=>showScenario('home');
  $('#family-tab').onclick=()=>showScenario('family');$('#calls-tab').onclick=$('#session-call').onclick=()=>showScenario('call');
  function formatted(id){return id.replace(/(\d{3})(\d{3})(\d{3})/,'$1 $2 $3');}
  function selectPeer(peer){chosen=peer;$('#target-input').value=peer.name;$('#target-error').textContent='';$('#target-suggestions').hidden=true;$('#target-input').setAttribute('aria-expanded','false');renderList();}
  function renderList(){
    const items=peers.filter(p=>list==='favorites'?p.favorite:list==='family'?p.family:true);
    const root=$('#home-device-list');root.replaceChildren();
    if(!items.length){const empty=document.createElement('div');empty.className='empty-list';empty.textContent=list==='family'?'Добавьте устройство по коду во вкладке «Семья».':'Пока пусто. Нажмите звезду рядом с устройством.';root.append(empty);return;}
    items.forEach(peer=>{
      const row=document.createElement('div');row.className='home-device-row'+(peer===chosen?' selected':'');
      const select=document.createElement('button');select.className='row-select';select.setAttribute('aria-label','Выбрать '+peer.name);const tile=document.createElement('span');tile.className='device-tile';tile.innerHTML=icon(peer.index>1?'mobile':'monitor');const text=document.createElement('span');text.className='row-text';const name=document.createElement('b');name.textContent=peer.name;const info=document.createElement('small');const dot=document.createElement('i');dot.className='status-dot'+(peer.online?'':' offline');info.append(dot,document.createTextNode((peer.online?'В сети':'Не в сети')+' · '+peer.os+' · '+formatted(peer.id)));text.append(name,info);select.append(tile,text);select.onclick=()=>selectPeer(peer);row.append(select);
      const star=document.createElement('button');star.className='favorite-button'+(peer.favorite?' is-favorite':'');star.textContent=peer.favorite?'★':'☆';star.setAttribute('aria-label',(peer.favorite?'Убрать из избранного: ':'В избранное: ')+peer.name);star.setAttribute('aria-pressed',String(peer.favorite));star.onclick=()=>{peer.favorite=!peer.favorite;renderList();};row.append(star);
      const connect=document.createElement('button');connect.className='row-connect';connect.textContent=peer.online?'↗':'—';connect.setAttribute('aria-label','Подключиться: '+peer.name);connect.disabled=!peer.online;connect.onclick=()=>{selectPeer(peer);startSession(peer,'screen');};row.append(connect);root.append(row);
    });
  }
  $$('[data-list]').forEach(b=>b.onclick=()=>{list=b.dataset.list;$$('[data-list]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));renderList();});
  function resolveTarget(){const raw=$('#target-input').value.trim().toLowerCase(),compact=raw.replace(/\s/g,'');const matches=peers.filter(p=>p.id===compact||p.name.toLowerCase()===raw);if(matches.length!==1){$('#target-error').textContent='Выберите известное устройство из подсказки. Реальные ID здесь не используются.';$('#target-input').setAttribute('aria-invalid','true');return null;}const peer=matches[0];if(!peer.online){$('#target-error').textContent='Устройство не в сети. Выберите другое в демо.';return null;}$('#target-input').removeAttribute('aria-invalid');$('#target-error').textContent='';return peer;}
  const input=$('#target-input');
  function suggestions(){const raw=input.value.trim().toLowerCase(),compact=raw.replace(/\s/g,'');const items=peers.filter(p=>!raw||p.name.toLowerCase().includes(raw)||p.id.includes(compact));const root=$('#target-suggestions');root.replaceChildren();suggestIndex=-1;items.forEach(peer=>{const b=document.createElement('button');b.type='button';b.textContent=peer.name;const small=document.createElement('small');small.textContent=formatted(peer.id)+' · '+(peer.online?'В сети':'Не в сети');b.append(small);b.onclick=()=>{selectPeer(peer);input.focus();};root.append(b);});root.hidden=!items.length;input.setAttribute('aria-expanded',String(!root.hidden));}
  input.addEventListener('input',suggestions);input.addEventListener('focus',suggestions);
  input.addEventListener('keydown',e=>{const opts=$$('#target-suggestions button');if((e.key==='ArrowDown'||e.key==='ArrowUp')&&opts.length){e.preventDefault();suggestIndex=(suggestIndex+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length;opts[suggestIndex].focus();}else if(e.key==='Enter'){e.preventDefault();$('#home-connect').click();}else if(e.key==='Escape'){$('#target-suggestions').hidden=true;input.setAttribute('aria-expanded','false');}});
  $('#target-suggestions').addEventListener('keydown',e=>{if(e.key==='Escape'){input.focus();$('#target-suggestions').hidden=true;input.setAttribute('aria-expanded','false');}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const opts=$$('#target-suggestions button'),i=opts.indexOf(document.activeElement);opts[(i+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length].focus();}});
  document.addEventListener('pointerdown',e=>{if(!e.target.closest('.autocomplete')){$('#target-suggestions').hidden=true;input.setAttribute('aria-expanded','false');}});
  function startSession(peer,action){
    if(!peer||!peer.online)return;if(peer.index>1&&(action==='files'||action==='terminal')){toast('Файлы и терминал мобильных устройств не реализованы в этом демо.');return;}
    clearTimeout(paneTimer);pendingAction=action;
    const tab=action==='files'?'files':action==='mobile'?'mobile':action==='connect'?'connect':'screen';showScenario(tab);
    document.querySelector('[data-device="'+peer.index+'"]').click();devices[peer.index].name=peer.name;devices[peer.index].label=peer.name.toUpperCase();$('#session-title').textContent=peer.name;$('#peer-label').textContent=peer.name.toUpperCase();$('#connect').click();
    paneTimer=setTimeout(()=>{paneTimer=null;if(!connected||selected!==peer.index)return;if(action==='files'){openFiles();$('#remote-screen').hidden=true;}else if(action==='terminal')openApp('terminal');else{$('#remote-screen').hidden=false;syncRights();}pendingAction=null;},1300);
  }
  $('#home-connect').onclick=()=>{const peer=resolveTarget();if(peer){selectPeer(peer);startSession(peer,'connect');}};
  $$('[data-home-action]').forEach(b=>b.onclick=()=>{const peer=resolveTarget();if(!peer)return;selectPeer(peer);if(b.dataset.homeAction==='call'){if(!peer.family){toast('В этом демо звонок доступен семейному устройству Family PC. Добавьте близкого по коду.');return;}showScenario('call');$('#family-member').value='mama';$('#family-member').dispatchEvent(new Event('change'));document.querySelector('#start-call').click();}else startSession(peer,b.dataset.homeAction);});
  $('#home-add-family').onclick=()=>showScenario('family');
  $('#copy-id').onclick=()=>copyMock('000 000 101 · FuntiDesk demo');
  $('#show-otp').onclick=()=>{shown=!shown;$('#otp-value').textContent=shown?otp:'••••••';$('#show-otp').setAttribute('aria-pressed',String(shown));$('#show-otp').setAttribute('aria-label',shown?'Скрыть демонстрационный пароль':'Показать демонстрационный пароль');};
  $('#refresh-otp').onclick=()=>{otp=otp==='DEMO01'?'DEMO02':'DEMO01';$('#otp-value').textContent=shown?otp:'••••••';toast('Одноразовый пароль обновлён в симуляции.');};
  $('#share-device').onclick=()=>{dialog('Поделиться доступом · демо','<p>Это вымышленные данные. Они не открывают доступ к реальному компьютеру.</p><pre class="dialog-share" id="share-preview"></pre><div class="dialog-actions"><button class="primary" id="copy-share">Скопировать</button></div>');const value='FuntiDesk · Home PC · DEMO\nID: 000 000 101\nОдноразовый пароль: '+otp;$('#share-preview').textContent=value;$('#copy-share').onclick=()=>copyMock(value);};
  function renderPermanent(){const b=$('#permanent-switch');b.setAttribute('aria-checked',String(permanent));$('#permanent-caption').textContent=permanent?'Включён · только в демо':'Выключен';}
  $('#permanent-switch').onclick=()=>{if(permanent){permanent=false;renderPermanent();toast('Постоянный доступ выключен в симуляции.');return;}dialog('Постоянный доступ · демо','<p>В клиенте эта настройка связана с постоянным паролем. Здесь показан только сценарий интерфейса: пароль DEMO-ONLY уже задан.</p><div class="dialog-share">DEMO-ONLY · вымышленный пароль</div><div class="dialog-actions"><button class="secondary" id="cancel-permanent">Отмена</button><button class="primary" id="confirm-permanent">Включить в демо</button></div>');$('#cancel-permanent').onclick=closeDialog;$('#confirm-permanent').onclick=()=>{permanent=true;renderPermanent();closeDialog();};};
  $('#hide-banner').onclick=()=>{$('#home-banner').hidden=true;toast('Приветствие скрыто. Его можно вернуть в настройках демо.');};
  $('#open-settings').onclick=()=>{dialog('Настройки · демо','<div class="settings-row"><span>Приветствие в главном окне</span><button id="restore-banner">Показать</button></div><div class="settings-row"><span>Анимация на сайте</span><button id="settings-motion"></button></div><div class="settings-row"><span>Тема</span><select id="settings-theme" data-theme-select aria-label="Тема сайта в настройках"><option value="light">Светлая</option><option value="dark">Тёмная</option><option value="system">Как в системе</option></select></div><p>Это настройки прототипа. Они не затрагивают установленный клиент.</p>');window.FuntiTheme.bindControls();$('#restore-banner').onclick=()=>{$('#home-banner').hidden=false;closeDialog();};const motion=$('#settings-motion');motion.textContent=paused?'Включить':'Приостановить';motion.onclick=()=>{$('#motion').click();motion.textContent=paused?'Включить':'Приостановить';};};
  $('#home-help').onclick=()=>{showScenario('family');document.querySelector('[data-journey="help"]').click();$('#family-member').value='mama';$('#family-member').dispatchEvent(new Event('change'));$('#request-help').click();};
  // Bridges the existing family flow to the separate session pane.
  const accepted=$('#accept-help').onclick;$('#accept-help').onclick=()=>{accepted();showScenario('screen');};
  $$('[data-family-action]').forEach(b=>{const old=b.onclick;b.onclick=()=>{old();if(busy)showScenario(b.dataset.familyAction==='files'?'files':'screen');};});
  const openShared=$('#call-open-screen').onclick;$('#call-open-screen').onclick=()=>{openShared();if(busy)showScenario('screen');};
  const oldReset=reset;reset=function(){clearTimeout(paneTimer);paneTimer=null;pendingAction=null;oldReset();};
  $('#client-close').onclick=()=>{reset();showScenario('home');toast('Демонстрационная сессия закрыта.');};
  $('#reset-prototype').onclick=()=>{reset();$('#family-restart').click();permanent=false;shown=false;otp='DEMO01';$('#otp-value').textContent='••••••';$('#show-otp').setAttribute('aria-pressed','false');$('#show-otp').setAttribute('aria-label','Показать демонстрационный пароль');$('#home-banner').hidden=false;$('#target-error').textContent='';$('#target-input').removeAttribute('aria-invalid');peers.forEach((p,i)=>{p.favorite=i===0||i===4;p.family=i===0;});list='recent';$$('[data-list]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.list==='recent')));selectPeer(peers[0]);renderPermanent();showScenario('home');toast('Демо сброшено.');};
  // Keep the visible family tab in sync with local pairing and rename flows.
  const familyUpdate=()=>{const select=$('#family-member');const m=select.value==='mama'?peers[0]:peers[4];m.family=$('#member-state').textContent.startsWith('В семье');m.name=$('#member-name').textContent;m.online=$('#member-online').checked;renderList();};
  new MutationObserver(familyUpdate).observe($('#member-state'),{childList:true});new MutationObserver(familyUpdate).observe($('#member-name'),{childList:true});$('#member-online').addEventListener('change',familyUpdate);
  $$('[data-device]').forEach((b,i)=>{b.querySelector('b').textContent=peers[i].name;});
  selectPeer(peers[0]);renderPermanent();showScenario('home');
})();
